                tiskDokladu() {
                    this.findFields().gfield("model", "collect", this.model);
                    const row = this.model;
                    let that = this;
                    let name;
                    if (row.druh_dok === 0 /* Hpl.Interface.DruhDokladu.danovy */) {
                        name = "pok_ptm_dokdan";
                    }
                    else if (row.druh_dok === 10 /* Hpl.Interface.DruhDokladu.nedanovy */) {
                        name = "pok_ptm_doklad";
                    }
                    else if (row.druh_dok === 20 /* Hpl.Interface.DruhDokladu.zjednoduseny */) {
                        name = "pok_ptm_dokzje";
                    }
                    const actVnitrniTiskDanove = GAction.createPrintAction({
                        name: "actTiskDanove",
                        caption: "jres:31302180", //RC 31302180 : Tisk daňových dokladů
                        tema: name,
                        serverParameterMethod: "Gordic.Pok.WebClient.GPokWebTisk:PokladniDoklad",
                        reportStarting: function (rep) {
                            rep.customDto = { list_ixp: that.model.ixp, ixp_den: that.model.ixp_den, vyskytOpisu: that.model.s_tis == 10, settingPocetKopii: that.model.ktg_typ == 1500 /* Hpl.Interface.KategorieTypu.prijmovy */ ? that.globalSettings.get("Pok.Nastaveni.PocKopii") : that.globalSettings.get("Pok.Nastaveni.PocKopiiVydajovy") };
                        },
                        reportFinished: function (event, retVal) {
                            if (that.pokParams.Faze == 0 /* Hpl.Interface.GPokFaze.POK */ || that.pokParams.Faze == 860 /* Hpl.Interface.GPokFaze.POZ */) {
                                if (that.pokParams.PokDokShodop && that.model.zpus_platby == 0) {
                                    that.showDopocetTab();
                                }
                            }
                            that.call("ZaznamenejTisk").done(function () {
                                that.load({ Ixp: that.model.ixp });
                            });
                        }
                    });
                    actVnitrniTiskDanove.run();
                }
                showDopocetTab() {
                    const that = this;
                    const headerForm = new Gordic.Forms.Form({ name: "pokDopocetkaForm" })
                        .addRow("Zaplaceno")
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "zaplaceno",
                        change: function (ev, changeObj) {
                            const zaplaceno = $(ev.target).closest(".gform").findFields("zaplaceno").gfield("getValue");
                            const castka = $(ev.target).closest(".gform").findFields("castka").gfield("getValue");
                            $(ev.target).closest(".gform").findFields("vratit").gfield("setValue", Decimal.sub(zaplaceno, castka));
                        }
                    })
                        .addRow("Částka")
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "castka", disabled: true, initialValue: that.model.c_celkem_m
                    })
                        .addRow("Vrátit")
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "vratit", disabled: true
                    });
                    that.dialogs.simpleForm("Dopočet", headerForm);
                }
