                            let ParamsJSON = { ixsVpk: that.ixsVpk, ktgTyp: that.element.findFields("ktg_typ").gfield("getValue").ktg_typ, ixpDen: that.model.ixp_den, uid: "'GPokVyberKontaceTab#'" };
