                                                    that.actions.actPokSchvaleniDokladu.setPending(100);
                                                    if (textRegistrDph !== '')
                                                        that.showPokFlashSuccess(textRegistrDph);
                                                    //showPokFlash smaže předchozí flashe a tak by smazal ten s textem registru DPH třeba
                                                    that.showFlash({ id: "flashWarning", icon: "", label: "Pokladní doklad byl schválen, ale platba kartou neproběhla korektně! Platbu můžete opakovat pomoci akce Platba kartou!", customClass: "g-state-warning" });
